unsigned long rotate_with_carry_loop_and_return(unsigned long Value, unsigned short Count)
{
	// Sol:Fresh ASM check3EC4..3ECE: XOR CH, JCXZ and repeated SHR DX/RCR AX agree for every low-BYTE count.
	// Sol: XOR CH,CH truncates count to low BYTE;0 leaves value unchanged.
	// Sol: Repeated SHR DX/RCR AX, NOT a host shift with count modulo32.
	for (unsigned short cx = (unsigned char)Count; cx != 0; --cx)
		Value >>= 1;
	return Value;
}
